    {σ : Fin (n1 + 1 + 1) → Fin (n + 1 + 1)} (hσ : IsReindexing c c1 σ) :
    IsReindexing (c ∘  (σ i).succSuccAbove (σ j))
      (c1 ∘ i.succSuccAbove j) (i.funPredPredAbove j hij σ hσ.1)

